import{_ as a,o as s,c as i,a2 as t}from"./chunks/framework.Bum8orMG.js";const k=JSON.parse('{"title":"Upgrade to v3","description":"Migrating KatanaKit from 2.x to 3 — the Prisma User model becomes Account and the accounts table must be renamed.","frontmatter":{"title":"Upgrade to v3","description":"Migrating KatanaKit from 2.x to 3 — the Prisma User model becomes Account and the accounts table must be renamed."},"headers":[],"relativePath":"guides/upgrade-to/v3.md","filePath":"guides/upgrade-to/v3.md","lastUpdated":1791014171000}'),n={name:"guides/upgrade-to/v3.md"};function o(d,e,l,r,h,c){return s(),i("div",null,[...e[0]||(e[0]=[t('<h1 id="upgrade-to-katanakit-v3" tabindex="-1">Upgrade to KatanaKit v3 <a class="header-anchor" href="#upgrade-to-katanakit-v3" aria-label="Permalink to &quot;Upgrade to KatanaKit v3&quot;">​</a></h1><p>This guide migrates you from <strong>2.x</strong> to <strong>3.x</strong>. One breaking change, and it touches the database.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> katanakit-js@^3</span></span></code></pre></div><h2 id="breaking-changes" tabindex="-1">Breaking changes <a class="header-anchor" href="#breaking-changes" aria-label="Permalink to &quot;Breaking changes&quot;">​</a></h2><h3 id="prisma-model-user-renamed-to-account-3-0-0" tabindex="-1">Prisma model <code>User</code> renamed to <code>Account</code> (3.0.0) <a class="header-anchor" href="#prisma-model-user-renamed-to-account-3-0-0" aria-label="Permalink to &quot;Prisma model `User` renamed to `Account` (3.0.0)&quot;">​</a></h3><p>In <code>katanakit-js/prisma</code>, the <code>User</code> model is now <code>Account</code>, mapped to the <code>accounts</code> table (<code>@@map(&quot;accounts&quot;)</code>), and <code>Post.author</code> points at it.</p><p>Before (2.x):</p><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">import</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> { usePrisma } </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">from</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;katanakit-js/prisma&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>\n<span class="line"></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> db</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> usePrisma</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">();</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> user</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> await</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> db.public.User.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">findUnique</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">({ where: { email } });</span></span></code></pre></div><p>After (3.x):</p><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> account</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> await</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> db.public.Account.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">findUnique</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">({ where: { email } });</span></span></code></pre></div><h3 id="the-table-rename-needs-a-migration" tabindex="-1">The table rename needs a migration <a class="header-anchor" href="#the-table-rename-needs-a-migration" aria-label="Permalink to &quot;The table rename needs a migration&quot;">​</a></h3><p>The database table is still called <code>users</code> until you rename it. On Postgres:</p><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">ALTER</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> TABLE</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;users&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> RENAME </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">TO</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;accounts&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span></code></pre></div><p>The <code>posts.authorId</code> foreign key keeps working — Postgres rewrites the reference when a table is renamed — but your Prisma migrations must know about it too. If you own the migration history:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> prisma</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> migrate</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dev</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --name</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rename_users_to_accounts</span></span></code></pre></div><p>Prisma will detect the drift and generate the migration; if you are applying this to a live database by hand, take the <code>ALTER TABLE</code> above and leave the migration file to the next <code>migrate dev</code> run.</p><div class="warning custom-block"><p class="custom-block-title">This is the only schema-breaking change in the library</p><p><code>Post.authorId</code> keeps its column name and type, and the other models (<code>Conversation</code>, <code>Message</code>) are untouched. Only <code>users</code> → <code>accounts</code> and every <code>db.public.User</code> reference in your code.</p></div><h2 id="added-in-v3" tabindex="-1">Added in v3 <a class="header-anchor" href="#added-in-v3" aria-label="Permalink to &quot;Added in v3&quot;">​</a></h2><ul><li><strong>Access-control service</strong> — a pure role/capability registry with hierarchy-based inheritance: <code>owner</code> &gt; <code>admin</code> &gt; <code>editor</code> &gt; <code>author</code> &gt; <code>member</code> &gt; <code>guest</code>. Exposes <code>useCan</code>, <code>useHasRole</code>, <code>useCapabilitiesFor</code>, <code>useRegisterRole</code>, <code>useRoles</code> and <code>useResetRoles</code>.</li><li><strong>Express access guard</strong> — <code>useRequireCapability(capability, resolveSubject)</code> in <code>katanakit-js/adapters/express</code> returns 401 for anonymous requests and 403 when the capability is missing. It plugs into the assistant router&#39;s existing <code>guard</code> seam and is unwired by default.</li></ul><h2 id="migration-checklist" tabindex="-1">Migration checklist <a class="header-anchor" href="#migration-checklist" aria-label="Permalink to &quot;Migration checklist&quot;">​</a></h2><ol><li>Install <code>katanakit-js@^3</code>.</li><li>Generate or apply the <code>users</code> → <code>accounts</code> migration.</li><li>Rename every <code>db.public.User</code> to <code>db.public.Account</code>.</li><li>Run your test suite.</li></ol><p>Full detail per release: <a href="/katanakit-js/changelog">changelog</a>.</p>',22)])])}const g=a(n,[["render",o]]);export{k as __pageData,g as default};
